/**
 * Passkeys.
 *
 * A thin seam over `@simplewebauthn/server`: it holds the relying-party identity,
 * the base64url ↔ bytes conversions, and nothing else. Keeping the library behind
 * one module means the ceremony details (which arguments both sides must agree on
 * — challenge, origin, rpID) are visible in a single file instead of scattered
 * through route handlers.
 *
 * Two rules the whole feature depends on:
 *
 *  - The **challenge** is generated by the server, stored, single-use and
 *    short-lived. It is the only thing that makes a response unreplayable.
 *  - The **origin** must be checked. Without it, a passkey registered for this
 *    site could be asserted from someone else's page.
 */

import {
  generateAuthenticationOptions,
  generateRegistrationOptions,
  verifyAuthenticationResponse,
  verifyRegistrationResponse,
  type AuthenticatorTransport,
  type AuthenticationResponseJSON,
  type PublicKeyCredentialCreationOptionsJSON,
  type PublicKeyCredentialRequestOptionsJSON,
  type RegistrationResponseJSON,
} from "@simplewebauthn/server";
import { env } from "../env.ts";

/** A credential as this database stores it. */
export interface StoredCredential {
  credentialId: string;
  /** The COSE public key, base64url. */
  publicKey: string;
  counter: number;
  transports: string[] | null;
}

/**
 * Base64url → bytes, copied into a fresh `Uint8Array`.
 *
 * The copy is not incidental: a Node `Buffer` is a view over a pooled
 * `ArrayBuffer`, and the library's types ask for a plain one.
 */
function toBytes(base64url: string): Uint8Array<ArrayBuffer> {
  const view = Buffer.from(base64url, "base64url");
  const bytes = new Uint8Array(view.length);
  bytes.set(view);
  return bytes;
}

function transportsOf(transports: string[] | null): AuthenticatorTransport[] | undefined {
  return transports && transports.length > 0 ? (transports as AuthenticatorTransport[]) : undefined;
}

export async function createRegistrationOptions(input: {
  userId: string;
  userName: string;
  displayName: string;
  /** Already-enrolled credentials, so the browser refuses to enrol one twice. */
  exclude: StoredCredential[];
}): Promise<PublicKeyCredentialCreationOptionsJSON> {
  return generateRegistrationOptions({
    rpName: env.rp.name,
    rpID: env.rp.id,
    // Stable per account, so a passkey created here is linked to this user on
    // every future sign-in rather than becoming an orphan the browser cannot map.
    userID: new TextEncoder().encode(input.userId),
    userName: input.userName,
    userDisplayName: input.displayName,
    attestationType: "none",
    excludeCredentials: input.exclude.map((credential) => ({
      id: credential.credentialId,
      transports: transportsOf(credential.transports),
    })),
    authenticatorSelection: {
      residentKey: "preferred",
      userVerification: "preferred",
    },
  });
}

export interface VerifiedCredential extends StoredCredential {
  deviceType: string;
  backedUp: boolean;
}

/** Verifies a registration ceremony, or null when the response does not hold up. */
export async function verifyRegistration(
  response: RegistrationResponseJSON,
  expectedChallenge: string,
): Promise<VerifiedCredential | null> {
  let result: Awaited<ReturnType<typeof verifyRegistrationResponse>>;
  try {
    result = await verifyRegistrationResponse({
      response,
      expectedChallenge,
      expectedOrigin: env.rp.origins,
      expectedRPID: env.rp.id,
      requireUserVerification: false,
    });
  } catch {
    // A malformed response — an unparsable attestation, a signature that is not
    // ASN.1 — makes the library throw rather than answer "not verified". Both are
    // the same thing to the caller, and neither is a server fault: this is input
    // from a browser, and a hand-built request should be refused, not a 500.
    return null;
  }

  if (!result.verified || !result.registrationInfo) return null;

  const { credential, credentialDeviceType, credentialBackedUp } = result.registrationInfo;
  return {
    credentialId: credential.id,
    publicKey: Buffer.from(credential.publicKey).toString("base64url"),
    counter: credential.counter,
    transports: credential.transports ?? null,
    deviceType: credentialDeviceType,
    backedUp: credentialBackedUp,
  };
}

export async function createAuthenticationOptions(
  allow: StoredCredential[],
): Promise<PublicKeyCredentialRequestOptionsJSON> {
  return generateAuthenticationOptions({
    rpID: env.rp.id,
    allowCredentials: allow.map((credential) => ({
      id: credential.credentialId,
      transports: transportsOf(credential.transports),
    })),
    userVerification: "preferred",
  });
}

export interface AssertionResult {
  /** The signature counter the authenticator reported. */
  newCounter: number;
  userVerified: boolean;
}

/**
 * Verifies an assertion against the stored public key, or null when it fails.
 *
 * A failure here is the expected outcome for a cloned authenticator: the counter
 * must never go backwards, and the library enforces that against the `counter` we
 * pass in.
 */
export async function verifyAuthentication(input: {
  response: AuthenticationResponseJSON;
  expectedChallenge: string;
  credential: StoredCredential;
}): Promise<AssertionResult | null> {
  let result: Awaited<ReturnType<typeof verifyAuthenticationResponse>>;
  try {
    result = await verifyAuthenticationResponse({
      response: input.response,
      expectedChallenge: input.expectedChallenge,
      expectedOrigin: env.rp.origins,
      expectedRPID: env.rp.id,
      credential: {
        id: input.credential.credentialId,
        publicKey: toBytes(input.credential.publicKey),
        counter: input.credential.counter,
        transports: transportsOf(input.credential.transports),
      },
      requireUserVerification: false,
    });
  } catch {
    // See the note on `verifyRegistration`: a signature the library cannot even
    // parse is a failed sign-in, not an internal error.
    return null;
  }

  if (!result.verified) return null;

  return {
    newCounter: result.authenticationInfo.newCounter,
    userVerified: result.authenticationInfo.userVerified,
  };
}

/** Local part / full address, masked for anything a caller other than the owner reads. */
export function maskDestination(destination: string | null): string | null {
  if (!destination) return null;

  if (destination.includes("@")) {
    const [local, domain] = destination.split("@");
    const head = local!.slice(0, 2);
    return `${local!.length > 2 ? head : local![0]}${"*".repeat(Math.max(1, local!.length - head.length))}@${domain}`;
  }

  // A phone number: keep the country code and the last three digits.
  const visible = 4;
  return destination.length <= visible
    ? "*".repeat(destination.length)
    : `${"*".repeat(destination.length - visible)}${destination.slice(-visible)}`;
}
